    "astroDialog": "<dialog id=\"astroDialog\">\r\n    <form method=\"dialog\">\r\n      <div class=\"dlg-actions su-d2d053\">\r\n        <h3 class=\"su-ee0cfe\">🔭 Eventos Astronómicos — Penco</h3>\r\n        <button type=\"button\" id=\"astroCloseTop\" class=\"btn btn-icon\" title=\"Cerrar\" aria-label=\"Cerrar\">✕</button>\r\n      </div>\r\n      <p class=\"muted su-77e2fe\">Cielo del Bío-Bío. Horas en <b>America/Santiago</b>. Arriba: salida y puesta de la luna en Penco (aprox.); fases en el calendario; aquí: eclipses, superlunas y lluvias de meteoros visibles desde Penco.</p>\r\n      <div class=\"timer-tabs su-4dca21\">\r\n        <button type=\"button\" id=\"tabAstroUpcoming\" class=\"btn btn-accent su-30e741\">⏳ Próximos</button>\r\n        <button type=\"button\" id=\"tabAstroMesLunar\" class=\"btn su-30e741\">🌕 Mes lunar</button>\r\n        <button type=\"button\" id=\"tabAstroYear\" class=\"btn su-30e741\">📅 Año</button>\r\n      </div>\r\n      <div id=\"astroTodayBox\" class=\"menstrual-card su-68a1a9\"></div>\r\n      <div id=\"astroList\"></div>\r\n      <p class=\"muted su-a953a7\">Fuentes: NASA/IMCCE efemérides. Lluvias: mejor madrugada, cielo oscuro, lejos de luces de Concepción. Eclipses: confirma visibilidad local.</p>\r\n      <div class=\"dlg-actions\"><button type=\"button\" id=\"astroClose\" class=\"btn\">Cerrar</button></div>\r\n    </form>\r\n  </dialog>\n",
